import {MockRepository} from './data/repository.js';
import {renderScene} from './scene-view.js';
import {CONTENT,WORKSPACE_COPY} from './content.js';
import {planMissingFields,transition} from './domain.js';
import {applyCue,bindSceneMotion,cueChange,readMotionPreference} from './motion.js';
import {AgentClient,AgentApiError} from './api/agent-client.js';
const repo=new MockRepository();
const app=document.querySelector('#app'),live=document.querySelector('#live-region');
const BUILD_VERSION='page-a-hitfix-2026-11-07';
const icons={leaf:'<path d="M20 4C9 4 4 8 4 15c0 3 2 5 5 5 7 0 11-5 11-16Z"/><path d="M4 20c4-5 7-8 13-12"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-6v-7h-4v7H4a1 1 0 0 1-1-1Z"/>',archive:'<path d="M4 4h16v4H4zM6 8v12h12V8M9 12h6"/>',sound:'<path d="M4 10v4h4l5 4V6l-5 4H4ZM17 9a5 5 0 0 1 0 6M19 6a9 9 0 0 1 0 12"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4.3 1.7c-1 .9-1.8 1.3-1.8 2.8M12 17h.01"/>',photo:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8.5" cy="9" r="1.5"/><path d="m21 15-5-5L5 20"/>',music:'<circle cx="9" cy="17" r="3"/><circle cx="18" cy="15" r="3"/><path d="M12 17V5l9-2v12"/>',heart:'<path d="M20.8 8.7c0 5.2-8.8 10.3-8.8 10.3S3.2 13.9 3.2 8.7A4.7 4.7 0 0 1 12 6a4.7 4.7 0 0 1 8.8 2.7Z"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.6a8 8 0 0 1-1.6.9l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.6-.9l-1.7.6-1.4-2.4 1.4-1.1a8 8 0 0 1 0-1.9l-1.4-1.1 1.4-2.4 1.7.6a8 8 0 0 1 1.6-.9l.3-1.8h2.8l.3 1.8a8 8 0 0 1 1.6.9l1.7-.6 1.4 2.4-1.4 1.1a8 8 0 0 1-.1 1.8Z"/>',book:'<path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v17H6.5A2.5 2.5 0 0 0 4 22Zm0 0V22"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',arrow:'<path d="M4 12h16m-7-7 7 7-7 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',play:'<path d="m8 5 12 7-12 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',check:'<path d="m5 12 4 4L19 6"/>',bin:'<path d="M4 7h16M10 11v6m4-6v6M6 7l1 14h10l1-14M9 7V4h6v3"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m14-13a4 4 0 1 1 0 8m4 5v-2a4 4 0 0 0-3-3.9M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',branch:'<path d="M12 21V9m0 0a5 5 0 1 0-5-5m5 5a5 5 0 1 1 5-5"/>',move:'<circle cx="12" cy="12" r="8"/><path d="M12 2v20M2 12h20m-3-3 3 3-3 3M5 9l-3 3 3 3m4-10 3-3 3 3m-6 14 3 3 3-3"/>',up:'<path d="m6 14 6-6 6 6"/>',down:'<path d="m6 10 6 6 6-6"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',minus:'<path d="M5 12h14"/>',reset:'<path d="M4 9a8 8 0 1 1 1 8M4 4v5h5"/>',motion:'<path d="M4 12h4l3-7 4 14 3-7h2"/>'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.leaf}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readBool=(key,fallback=false)=>{const value=localStorage.getItem(key);return value===null?fallback:value==='true'};
const saveUiPreference=(key,value)=>localStorage.setItem(key,String(Boolean(value)));
const state={group:'group-home',member:'member-a',scene:'garden',tab:'space',purpose:'memory',records:[],mappings:[],monument:null,selected:null,currentDiscId:sessionStorage.getItem('mg-current-disc'),detail:null,filter:'all',view:'overview',align:null,quiet:readBool('mg-pets-quiet'),ambient:readBool('mg-ambient-enabled'),audio:false,playing:false,audioProgress:0,audioVolume:Number(localStorage.getItem('mg-record-volume')||50),captions:readBool('mg-captions',true),veil:readBool('mg-memory-veil'),reduceMotion:readMotionPreference(),sceneControlsOpen:false,camera:{x:0,y:0,zoom:1},seconds:60,modal:null,origin:null,kind:null,returnFocus:null,sceneObserver:null,motionCleanup:null,sceneInteractionCleanup:null,motionCue:null,motionTimer:null};
const agent=new AgentClient({actorId:()=>state.member});
const names=CONTENT.pages;
function announce(s){live.textContent=s}
function scenePage(){return renderScene({state,header,icon,esc,detailPanel,modal})}
function route(){const p=location.pathname.split('/').filter(Boolean);if(p[0]==='r') {state.group=p[1]||state.group;if(p[2]==='space'){state.tab='space';state.scene=p[3]==='home'?'home':'garden'}if(p[2]==='workspace'){state.tab=p[3]==='archive'?'archive':p[3]==='alignment'?'alignment':p[3]==='settings'?'settings':'new';if(p[4])state.detail=p[4]}}const u=new URL(location.href);state.selected=u.searchParams.get('object')||null;}
async function go(path){history.pushState({},'',path);state.detail=null;route();await refresh();render()}
window.addEventListener('popstate',()=>{route();render()});
function group(){return state.group==='group-home'?'我的家人':'挚友之间'}
async function refresh(){const previous=new Set(state.mappings.map(item=>item.imageryId));const previousMonument=state.monument?.confirmedAlignmentCount||0;state.records=await repo.getRecords(state.group,state.member);state.mappings=await repo.scene(state.group,state.scene);state.align=await repo.alignment(state.group);state.monument=await repo.monument(state.group);if(state.hasRefreshed){const added=state.mappings.find(item=>!previous.has(item.imageryId));if(added)cueChange(state,{type:added.imageryType,imageryId:added.imageryId,sourceRecordId:added.sourceRecordId,message:'已整理为新的场景意象'});if((state.monument?.confirmedAlignmentCount||0)>previousMonument)cueChange(state,{type:'alignment',message:'已为对齐纪念增加新的标记'})}state.hasRefreshed=true;if(state.currentDiscId&&!state.mappings.some(m=>m.imageryId===state.currentDiscId))state.currentDiscId=null}
function header(space=false){return `<header class="topbar" data-build="${BUILD_VERSION}"><a class="brand" href="#" data-home>${icon('leaf')}<span><i>Memory Garden</i><b>记忆花园</b></span></a>${space?`<nav class="scene-nav" aria-label="场景切换"><button class="${state.scene==='garden'?'active':''}" data-scene="garden">${icon('leaf')}花园</button><button class="${state.scene==='home'?'active':''}" data-scene="home">${icon('home')}老屋</button></nav>`:''}<div class="top-actions"><label class="group-select">${icon('users')}<span class="wide-label">关系组</span><select aria-label="选择关系组" id="group-select"><option value="group-home" ${state.group==='group-home'?'selected':''}>我的家人</option><option value="group-friends" ${state.group==='group-friends'?'selected':''}>挚友之间</option></select></label><button class="btn small" data-ambient aria-label="${state.ambient?'关闭氛围音':'开启氛围音'}" aria-pressed="${state.ambient}">${icon('sound')}<span class="wide-label">声音${state.ambient?'：已开':'：静音'}</span></button><button class="btn small" data-help aria-label="打开帮助">${icon('help')}<span class="wide-label">帮助</span></button>${space?`<button class="btn warm archive-jump" data-tab="archive">${icon('book')}查看文字档案与对齐记录</button>`:`<button class="btn" data-space>${icon('home')}返回记忆空间</button>`}</div></header>`}
function legacyScenePage(){const home=state.scene==='home';const flowers=state.mappings.filter(m=>m.type==='flower'||m.type==='leaf');const branches=state.mappings.filter(m=>m.type==='branch');const records=state.mappings.filter(m=>m.type==='record');const demoEmpty=state.records.length===0;return `${header(true)}<main id="main" class="scene-page ${home?'home-scene':'garden-scene'} ${state.veil?'veiled':''}" tabindex="-1"><div class="scene-art-status" role="note"><span>${icon('photo')}</span><div><b>${home?'老屋庭院':'花园'}分层插画待接入</b><small>当前交付保留真实交互与数据映射；未用几何图形冒充最终插画。</small></div></div><aside class="scene-switcher card"><h2>场景</h2><button data-scene="garden" class="${!home?'chosen':''}">${icon('leaf')}花园</button><button data-scene="home" class="${home?'chosen':''}">${icon('home')}老屋·庭院</button></aside><section class="scene-stage" aria-labelledby="scene-title"><div class="stage-copy"><span class="eyebrow">页面 A · 意象展示端</span><h1 id="scene-title">${home?'老屋庭院':'记忆花园'}</h1><p>这里只呈现已确认、已归档并完成映射的意象；敏感原文与认知对齐输入不会进入本页。</p></div><div class="scene-objects" aria-label="共同记忆意象">${flowers.map((m,i)=>`<button class="object object-placeholder flower f${i%6}" data-object="${esc(m.id)}" aria-label="照片意象：${esc(m.title)}">${icon('leaf')}<span>照片意象</span></button>`).join('')}${branches.map((m,i)=>`<button class="object object-placeholder branch b${i%5}" data-object="${esc(m.id)}" aria-label="心愿树枝叶：${esc(m.title)}">${icon('branch')}<span>心愿枝叶</span></button>`).join('')}${records.map(m=>`<button class="object object-placeholder record-object" data-object="${esc(m.id)}" aria-label="记忆唱片：${esc(m.title)}">${icon('music')}<span>记忆唱片</span></button>`).join('')}</div>${!state.mappings.length?`<div class="stage-empty"><b>当前场景暂无已映射意象</b><span>切换场景，或在页面 B 新建并确认记录。</span></div>`:''}</section><div class="pet-card card"><span class="pet-illustration" aria-hidden="true">${icon('users')}</span><div><strong>双人桌宠</strong><small>${state.quiet?'已休眠':'安静休息'} · 插画待接入</small></div><button class="btn small" data-quiet>${state.quiet?'唤醒':'一键休眠'}</button></div><section class="growth-card card"><div class="section-title"><h2>近期场景变化</h2><button class="text-button" data-why>为什么出现这个变化？</button></div><p>${demoEmpty?'这里会呈现已确认记录带来的场景变化。':`演示数据：${flowers.length} 个图片意象、${branches.length} 个心愿枝叶、${records.length} 张唱片。`}</p><div class="growth-steps" aria-label="场景成长阶段"><span>花苞</span><i></i><span>新叶</span><i></i><span>开花</span></div></section>${demoEmpty?`<section class="empty-callout card"><h2>从第一条记忆开始</h2><p>添加并确认一条记录后，这里才会出现对应意象。</p><button class="btn primary" data-tab="new">${icon('plus')}添加第一张照片</button></section>`:''}<section class="record-shelf card"><div class="section-title"><h2>记忆唱片</h2><span class="tag">${records.length} 条已映射</span></div>${records.length?`<div class="records">${records.map(m=>`<button class="record-disc" data-object="${esc(m.id)}" aria-label="选择唱片：${esc(m.title)}"><span>${icon('music')}</span><b>${esc(m.title)}</b></button>`).join('')}</div><div class="audio-controls"><button class="btn small" data-play>${icon(state.playing?'pause':'play')}${state.playing?'暂停':'播放所选唱片'}</button><label>唱片音量 <input type="range" min="0" max="100" value="${state.audioVolume??50}" data-volume aria-label="唱片音量"></label><button class="btn small" data-caption aria-pressed="${state.captions!==false}">字幕${state.captions===false?'关':'开'}</button></div>`:`<p class="muted">暂无已映射音频。新增并确认音频后，唱片会出现在这里。</p>`}</section><button class="fixed-archive" data-tab="archive">${icon('book')}查看文字档案与对齐记录${icon('arrow')}</button>${state.selected?detailPanel():''}${state.modal?modal():''}</main>`}
function detailPanel(){
 const m=state.mappings.find(x=>x.imageryId===state.selected);
 if(!m)return '';
 const photo=['flower','petal','leaf'].includes(m.imageryType);
 const body=photo?`${m.imageUrl?`<img class="detail-photo" src="${esc(m.imageUrl)}" alt="${esc(m.eventName)}" width="320" height="220">`:'<p class="hint">演示图片记录未附原图文件。</p>'}<dl class="detail-facts"><div><dt>事件名称</dt><dd>${esc(m.eventName)}</dd></div><div><dt>日期和时间</dt><dd>${esc(m.occurredAt||'未提供')}</dd></div><div><dt>地点</dt><dd>${esc(m.location||'未提供')}</dd></div><div><dt>一句话备注</dt><dd>${esc(m.note||'未提供')}</dd></div><div><dt>可见范围</dt><dd>${m.visibility==='group'?'关系组可见':'仅自己可见'}</dd></div>${m.confirmedEmotionTag?`<div><dt>已确认情绪标签</dt><dd>${esc(m.confirmedEmotionTag)}</dd></div>`:''}</dl>`:
 `<div class="summary-box"><strong>意象摘要</strong><p>${esc(m.summary||'由已确认记录转译的中性意象。')}</p></div>${m.emotionTag?`<p>已确认情绪标签：${esc(m.emotionTag)}</p>`:''}`;
 return `<div class="panel-scrim" data-close></div><aside class="detail-panel card" role="dialog" aria-modal="true" aria-labelledby="detail-title"><button class="close-btn" data-close aria-label="关闭详情">${icon('close')}</button><span class="tag">已确认意象 · 演示数据</span><h2 id="detail-title">${esc(m.title)}</h2>${body}<p class="explanation"><b>为什么出现这个变化？</b><br>${esc(m.explanation)}</p>${m.imageryType==='record'?`<button class="btn primary" data-load-disc="${esc(m.imageryId)}">${icon('music')}放到留声机播放</button>`:''}<button class="btn" data-source="${esc(m.sourceRecordId)}">${icon('archive')}查看来源档案</button></aside>`;
}
function sidebar(){return `<aside class="workspace-side"><div class="side-group"><span>当前关系组</span><b>${esc(group())}</b></div><nav aria-label="工作区导航">${Object.entries(names).map(([id,n])=>`<button data-tab="${id}" class="${state.tab===id?'selected':''}">${icon(id==='new'?'plus':id==='archive'?'archive':id==='alignment'?'users':'settings')}${n}</button>`).join('')}</nav></aside>`}
function workspace(){return `${header(false)}<div class="workspace-shell">${sidebar()}<main id="main" class="workspace-main" tabindex="-1"><div class="page-heading"><div><span class="eyebrow">页面 B · 工作区</span><h1>${names[state.tab]}</h1><p>演示数据保存在此浏览器中。</p></div><span class="tag">${esc(group())}</span></div>${state.tab==='new'?newRecord():state.tab==='archive'?archivePage():state.tab==='alignment'?alignmentPage():settingsPage()}</main></div><nav class="mobile-tabs" aria-label="工作区导航">${Object.entries(names).map(([id,n])=>`<button data-tab="${id}" class="${state.tab===id?'selected':''}">${icon(id==='new'?'plus':id==='archive'?'archive':id==='alignment'?'users':'settings')}<span>${n}</span></button>`).join('')}</nav>${state.modal?modal():''}`}
function newRecord(){return `<section class="card form-card"><div class="section-kicker">${icon('leaf')} 温柔沟通工作台</div><h2>选择记录用途</h2><div class="purpose-grid">${[['memory','普通记忆'],['emotion','情绪表达'],['plan','计划 / 心愿'],['alignment','发起认知对齐']].map(([k,l])=>`<button class="purpose ${state.purpose===k?'on':''}" data-purpose="${k}">${l}</button>`).join('')}</div><div class="entry-grid"><button class="entry" data-kind="text">${icon('book')}<b>写一段话</b><small>文本记录或计划说明</small></button><button class="entry" data-kind="voice">${icon('sound')}<b>说给花园听</b><small>浏览器内本地模拟转写</small></button><button class="entry" data-kind="image">${icon('photo')}<b>添加照片</b><small>选择图片并补充事件信息</small></button><button class="entry" data-kind="audio">${icon('music')}<b>添加音频</b><small>选择本地音频文件</small></button></div><div id="composer">${state.kind?composer():`<div class="composer-empty"><b>从一种记录方式开始</b><span>输入、确认和版本选择都只发生在页面 B。</span></div>`}</div></section><section class="card safety-note"><h2>演示说明</h2><p>AI 处理、高危触发与语音转写均为本地模拟，不代表真实 AI 服务。样例条目会明确标注“演示数据”。</p></section>`}
function composer(){const k=state.kind||'text';const visibility=`<label class="field">可见范围<select name="visibility"><option value="self">${WORKSPACE_COPY.visibility.self}</option><option value="group">${WORKSPACE_COPY.visibility.group}</option></select></label>`;const plan=state.purpose==='plan'?`<fieldset class="plan-fields"><legend>结构化计划（可修改）</legend><div class="form-grid"><label class="field">日期<input name="planDate" type="date"></label><label class="field">时间<input name="planTime" placeholder="例如 18:30"></label><label class="field">时区<input name="timezone" value="Asia/Shanghai"></label><label class="field">地点<input name="planPlace"></label><label class="field">参与人<input name="participants"></label><label class="field">动作<input name="action"></label><label class="field">出发 / 到达<select name="timeMeaning"><option value="">待确认</option><option>出发时间</option><option>到达时间</option></select></label><label class="field">提醒方式<input name="reminder" placeholder="仅记录，不创建真实提醒"></label></div><p class="hint">关键字段未确认时不会标记为完整或生成共享枝叶。</p></fieldset>`:'';return `<form id="record-form" class="composer" novalidate><div class="composer-head"><h2>${k==='image'?'图片记录':k==='audio'?'音频记录':k==='voice'?'语音转写演示':state.purpose==='emotion'?'情绪表达':state.purpose==='plan'?'计划 / 心愿':'文本记录'}</h2><button type="button" class="text-button" data-clear-kind>关闭</button></div>${k==='image'||k==='audio'?`<label class="field">${k==='image'?'选择图片':'选择音频'}<input type="file" name="file" accept="${k==='image'?'image/*':'audio/*'}" required><span class="hint">仅本机预览；刷新后浏览器可能清除预览地址。</span></label>`:''}${k==='voice'?`<div class="voice-box"><button type="button" class="btn" data-voice>生成本地转写演示</button><p>不会上传录音；可在下方编辑转写文本。</p></div>`:''}<label class="field">${state.purpose==='emotion'?'你的原话':k==='voice'?'转写文本':k==='image'||k==='audio'?'补充说明':'记录内容'}<textarea name="content" rows="4" placeholder="仅页面 B 输入；确认前不会共享或映射。" ${k==='image'||k==='audio'?'':'required'}></textarea></label>${k==='image'?`<div class="form-grid"><label class="field">事件名称<input name="title" required></label><label class="field">时间<input name="date" type="date"></label><label class="field">地点<input name="place"></label><label class="field">图片意象<select name="imageryType"><option value="flower">花朵</option><option value="petal">花瓣</option><option value="leaf">树叶</option></select></label></div>`:''}${k==='audio'?`<div class="form-grid"><label class="field">标题<input name="title" required></label><label class="field">音频类型<select name="audioType">${WORKSPACE_COPY.audioTypes.map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field">演唱者 / 录制者<input name="creator"></label><label class="field">备注<input name="note"></label></div>`:''}${plan}${state.purpose==='emotion'?`<div class="candidate-area" id="candidate-area"></div>`:''}${state.purpose==='plan'?`<div class="candidate-area" id="candidate-area"><p class="hint">若“六点半”未能判断出发或到达语义，Demo 会逐项追问。</p></div>`:''}${visibility}<div class="form-actions"><button type="submit" class="btn primary">${state.purpose==='emotion'?'分析并查看候选':state.purpose==='plan'?'确认计划':'确认并归档'}</button><button type="button" class="btn" data-abandon>放弃本次</button></div><div id="form-feedback" role="status"></div></form>`}
function archivePage(){const filters=state.archiveFilters||{type:'all',visibility:'all',mapped:'all',member:'all'};const records=state.records.filter(r=>(filters.type==='all'||r.kind===filters.type)&&(filters.visibility==='all'||r.visibility===filters.visibility)&&(filters.mapped==='all'||(filters.mapped==='yes'?!!r.mappingId:!r.mappingId))&&(filters.member==='all'||r.authorId===filters.member)&&(!state.query||`${r.title} ${r.summary} ${r.confirmedEmotionTag||''}`.toLowerCase().includes(state.query.toLowerCase())));const opts=(key,items)=>`<label class="field compact">${key}<select data-archive-filter="${key}">${items.map(([v,l])=>`<option value="${v}" ${filters[key]===v?'selected':''}>${l}</option>`).join('')}</select></label>`;return `<section class="card"><div class="filter-row">${opts('type',[['all','全部类型'],['text','文本'],['image','图片'],['audio','音频']])}${opts('visibility',[['all','全部可见范围'],['group','关系组可见'],['self','仅自己可见']])}${opts('mapped',[['all','全部映射状态'],['yes','已映射'],['no','未映射']])}${opts('member',[['all','全部成员'],['member-a','成员 A'],['member-b','成员 B']])}<label class="field compact">搜索<input data-search value="${esc(state.query||'')}" placeholder="标题、摘要或已确认标签"></label><button class="btn small" data-reset>重置 Demo 数据</button></div><p class="hint">共 ${records.length} 条可查看档案；所有条目均为本地 Demo 数据。</p>${records.length?`<div class="archive-list">${records.map(r=>`<article class="archive-row"><div><div class="row-title">${esc(r.title)} ${r.source==='demo'?'<span class="tag">演示数据</span>':''}</div><p>${esc(r.summary||'')}</p><small>${r.authorId==='member-a'?'成员 A':'成员 B'} · ${esc(r.date||'未提供时间')} · ${r.kind==='audio'?'音频':r.kind==='image'?'图片':'文本'} · ${statusLabel(r.status)} · ${r.visibility==='self'?'仅自己可见':'关系组可见'}${r.confirmedEmotionTag?` · 已确认标签：${esc(r.confirmedEmotionTag)}`:''}</small></div><button class="btn small" data-record="${esc(r.id)}">查看详情</button></article>`).join('')}</div>`:`<div class="empty-state"><h2>${state.records.length?'没有匹配的档案':'暂无档案'}</h2><p>${state.records.length?'调整筛选条件后再试。':'新建并确认记录后会出现在这里。'}</p><button class="btn primary" data-tab="new">新建记录</button></div>`}${state.detail?recordDetail():''}</section>`}
function statusLabel(s){return ({draft:'草稿',cooling:'冷静期中',archived:'已归档',mapped:'已映射',private:'仅自己可见',deleted:'已删除'})[s]||s}
function recordDetail(){const r=state.records.find(x=>x.id===state.detail);if(!r)return '';return `<div class="inline-detail" role="region" aria-labelledby="record-title"><button class="close-btn" data-close-detail aria-label="关闭详情">${icon('close')}</button><h2 id="record-title">${esc(r.title)}</h2><span class="tag">${statusLabel(r.status)}</span><p>${esc(r.summary||'')}</p>${r.privateText?`<div class="sensitive"><b>原始输入（页面 B）</b><p>${esc(r.privateText)}</p></div>`:''}${r.candidate?`<div class="compare"><div><b>润色候选</b><p>${esc(r.candidate)}</p></div><div><b>最终选择</b><p>${esc(r.finalChoice||'')}</p></div></div>`:''}<p>创建时间：${r.createdAt?new Date(r.createdAt).toLocaleString():'演示样例'}</p>${r.mappingId?`<button class="btn" data-locate="${esc(r.mappingId)}">在空间中查看</button>`:''}<button class="btn danger" data-delete="${esc(r.id)}">${icon('bin')}删除记录</button></div>`}
function alignmentPage(){const a=state.align;if(!a)return `<section class="card empty-state"><h2>暂无认知对齐会话</h2><p>该功能由用户主动发起。</p><button class="btn primary" data-start-alignment>发起演示会话</button></section>`;const me=a.participants.find(p=>p.id===state.member);const other=a.participants.find(p=>p.id!==state.member);const ready=a.participants.every(p=>p.submitted&&p.reviewed&&p.analysisConfirmed);return `<section class="card alignment-board"><div class="alignment-status"><span class="tag">${a.source==='demo'?'演示会话':''} 双方输入相互隔离</span><h2>${esc(a.title)}</h2><p>会话进度：${ready?'双方已完成本人核验':'等待双方分别完成提交与本人核验'}</p><p class="hint">完成对齐仅表示双方完成核验，不代表关系已修复。</p></div><div class="tabs" role="tablist" aria-label="对齐视图"><button role="tab" aria-selected="${state.view==='overview'}" data-view="overview">错位摘要</button><button role="tab" aria-selected="${state.view==='mine'}" data-view="mine">我的视角</button><button role="tab" aria-selected="${state.view==='other'}" data-view="other">另一方视角</button></div>${state.view==='overview'?`<div class="mismatch-list">${a.mismatches.map((m,i)=>`<div class="mismatch"><span class="mismatch-mark">${icon(i?'heart':'help')}</span><b>${esc(m)}</b><span>存在理解差异</span></div>`).join('')}</div>${ready?`<div class="alignment-dual" aria-label="双方已确认解析对照">${participantCard(me,true)}${participantCard(other,false)}</div>`:''}`:''}${state.view==='mine'?participantCard(me,true):''}${state.view==='other'?(ready?participantCard(other,false):`<div class="privacy-gate"><h3>另一方尚未完成本人核验</h3><p>为保护隐私，当前不展示对方的输入或解析。</p></div>`):''}${!me.reviewed?`<div class="form-actions"><button class="btn primary" data-review>确认这是我的意思</button><button class="btn" data-edit-analysis>修改我的解析</button><button class="btn" data-not-mine>不是我的意思</button></div>`:`<p class="hint">你已核验自己的解析。需要更改时可在此演示中切换成员视角。</p>`}<div class="form-actions"><button class="btn" data-supplement>各自补充说明</button><button class="btn primary" data-save-alignment ${ready?'':'disabled'}>保存本次对齐（双方核验后）</button><button class="btn" data-end-alignment>暂时结束</button></div></section>`}
function participantCard(p,self){return `<article class="participant"><h3>${self?'我的解析':'另一方已核验解析'} <span class="tag ${p.reviewed?'good':'wait'}">${p.reviewed?'已核验':'待核验'}</span></h3><div class="field-list">${Object.entries({事实描述:p.fields.fact,当下情绪:p.fields.emotion,内在诉求:p.fields.need,未说出口的期待:p.fields.expectation,对对方话语的理解:p.fields.understanding,不确定项:p.fields.uncertain}).map(([k,v])=>`<div><b>${k}</b><p>${esc(v)}</p></div>`).join('')}</div></article>`}
function settingsPage(){return `<section class="card settings-grid"><article><h2>关系成员与演示视角</h2><p>当前关系组：${esc(group())}。成员名称为演示标签，不代表真实身份。</p><label class="field">当前演示成员<select id="member-select"><option value="member-a" ${state.member==='member-a'?'selected':''}>成员 A</option><option value="member-b" ${state.member==='member-b'?'selected':''}>成员 B</option></select></label></article><article><h2>隐私与记忆帷幕</h2><p>记忆帷幕仅在当前演示设备模糊场景，不改变记录权限。</p><button class="btn" data-veil>${state.veil?'关闭记忆帷幕':'开启记忆帷幕'}</button></article><article><h2>领地状态</h2><p>当前状态：${state.archived?'双向归档演示':'活跃共建演示'}。双向归档后历史只读。</p><button class="btn" data-territory>${state.archived?'恢复演示活跃状态':'演示双向归档'}</button></article><article><h2>安全演示</h2><p>测试关键词仅触发本地模拟安全边界，不进行诊断。正式援助资源：待接入可验证本地资源。</p><button class="btn" data-crisis>查看安全分流演示</button></article><article><h2>重置本地演示数据</h2><p>清除本应用 Demo 记录、会话和预览状态，重新加载明确标记的样例。</p><button class="btn danger" data-reset>${icon('bin')}重置 Demo 数据</button></article></section>`}
function modal(){return `<div class="modal-backdrop" data-modal-bg><section class="modal card" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="close-btn" data-modal-close aria-label="关闭">${icon('close')}</button><h2 id="modal-title">${esc(state.modal.title)}</h2><div>${state.modal.body}</div><div class="form-actions">${state.modal.actions||'<button class="btn primary" data-modal-close>知道了</button>'}</div></section></div>`}
function render(){const space=state.tab==='space';state.motionCleanup?.();state.motionCleanup=null;state.sceneInteractionCleanup?.();state.sceneInteractionCleanup=null;app.innerHTML=space?scenePage():workspace();bind();if(space){bindSceneObjects();state.sceneInteractionCleanup=bindSceneInteractions();state.motionCleanup=bindSceneMotion({root:app,state,onRender:render,onAnnounce:announce});applyCue(app,state,announce)}app.querySelectorAll('.scene-canvas img').forEach(img=>img.addEventListener('error',()=>console.error('Scene asset failed to load:',img.getAttribute('src'))));if(state.selected)app.querySelector('.detail-panel .close-btn')?.focus();if(state.detail)app.querySelector('[data-close-detail]')?.focus();}
function bindSceneInteractions(){
 const root=app.querySelector('.scene-page.illustrated');
 if(!root)return ()=>{};
 const remember=(target)=>{const id=target?.dataset?.id;state.returnFocus=id?`[data-id="${CSS.escape(id)}"]`:focusSelector(target)};
 const handle=(event)=>{
  const target=event.target.closest?.('[data-action]');
  if(!target||!root.contains(target))return;
  event.preventDefault();event.stopPropagation();
  const action=target.dataset.action;
  if(action==='open-imagery'){remember(target);state.selected=target.dataset.id;history.replaceState({},'',`/r/${state.group}/space/${state.scene}?object=${encodeURIComponent(state.selected)}`);render();return}
  if(action==='toggle-gramophone'){remember(target);const records=state.mappings.filter(m=>m.imageryType==='record');if(!records.length){showModal('记忆留声机','请先从唱片收藏中选择一张唱片。');return}if(!state.currentDiscId){showModal('记忆留声机','请先从唱片收藏中选择一张唱片。');return}playAudio();return}
  if(action==='open-collection'){remember(target);const records=state.mappings.filter(m=>m.imageryType==='record');showModal('记忆唱片收藏',records.length?`<p>当前收藏 ${records.length} 张演示唱片，请选择一张查看详情。</p>`:'<p>当前没有可播放的记忆唱片。</p>');return}
  if(action==='open-pets'){remember(target);const count=state.mappings.length;showModal('双人桌宠近期变化',count?`<p>近期已整理 ${count} 条场景变化，桌宠会保持${state.quiet?'休眠':'安静陪伴'}。</p>`:'<p>当前暂无新的变化，桌宠正在安静休息。</p>');return}
  if(action==='open-memorial'){remember(target);const monument=state.monument;if(!monument){showModal('对齐纪念','当前关系组没有可显示的确认对齐。');return}showModal('对齐纪念',`<p>这是双方本人核验并确认保存的一次理解整理记录。</p><dl class="detail-facts"><div><dt>完成日期</dt><dd>${esc(monument.confirmedAt||'演示日期')}</dd></div><div><dt>确认次数</dt><dd>${monument.confirmedAlignmentCount||1}</dd></div><div><dt>中性结果摘要</dt><dd>存在过一次被双方确认的理解整理。</dd></div></dl>`,`<button class="btn primary" data-alignment-source="${esc(monument.latestAlignmentId||'align-demo-1')}">${icon('archive')}查看对齐记录</button><button class="btn" data-modal-close>关闭</button>`);return}
  if(action==='open-phantom'){remember(target);showModal('尚未完成的理解差异','这里仅提示仍有待整理的理解差异，不会展示或复制对方原文。',`<button class="btn primary" data-start-alignment>发起认知对齐</button><button class="btn" data-modal-close>暂时关闭</button>`);return}
 };
 const handleKey=(event)=>{
  if((event.key==='Enter'||event.key===' ')&&!event.defaultPrevented){
   const target=event.target.closest?.('[data-action]');
   if(target&&root.contains(target)){event.preventDefault();target.click();}
  }
 };
 root.addEventListener('click',handle,{capture:true});
 root.addEventListener('keydown',handleKey,{capture:true});
 return ()=>{root.removeEventListener('click',handle,{capture:true});root.removeEventListener('keydown',handleKey,{capture:true})};
}
function bindSceneObjects(){
 const viewport=app.querySelector('.scene-viewport'),canvas=app.querySelector('.scene-canvas');
 state.sceneObserver?.disconnect();
 if(viewport&&canvas){const fit=()=>canvas.style.setProperty('--scene-scale',String(Math.max(viewport.clientWidth/1440,viewport.clientHeight/900)));fit();state.sceneObserver=new ResizeObserver(fit);state.sceneObserver.observe(viewport)}
 app.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>{
  const selected=state.selected;
  state.selected=null;
  history.replaceState({},'',`/r/${state.group}/space/${state.scene}`);
  render();
  app.querySelector(`[data-object="${CSS.escape(selected||'')}"]`)?.focus();
 });
 app.querySelector('[data-gramophone]')?.addEventListener('click',()=>{const records=state.mappings.filter(m=>m.imageryType==='record');if(!records.length){showModal('记忆留声机','还没有可播放的记忆唱片。');return}if(!state.currentDiscId){showModal('记忆留声机','请先从唱片收藏中选择一张唱片。');return}playAudio()});
 app.querySelector('[data-collection]')?.addEventListener('click',()=>{const records=state.mappings.filter(m=>m.imageryType==='record');showModal('记忆唱片收藏',records.length?`<p>当前收藏 ${records.length} 张已归档且授权播放的演示唱片。请选择场景中的具体唱片查看详情。</p>`:'<p>当前没有已归档且授权播放的唱片。</p>')});
 app.querySelector('[data-load-disc]')?.addEventListener('click',async e=>{const discId=e.currentTarget.dataset.loadDisc;state.selected=null;await animateDiscToGramophone(discId);state.currentDiscId=discId;sessionStorage.setItem('mg-current-disc',discId);cueChange(state,{type:'record',imageryId:discId,message:'唱片已装入留声机'});announce('唱片已放到留声机，点击留声机可播放或暂停');render()});
  app.querySelector('[data-stop]')?.addEventListener('click',()=>{state.audioElement?.pause();if(state.audioElement)state.audioElement.currentTime=0;state.playing=false;state.audioProgress=0;render();announce('已停止播放')});
  app.querySelector('[data-progress]')?.addEventListener('input',event=>{if(!state.audioElement?.duration)return;state.audioElement.currentTime=state.audioElement.duration*(Number(event.currentTarget.value)/100);state.audioProgress=Number(event.currentTarget.value)});
 app.querySelectorAll('[data-pet]').forEach(button=>button.addEventListener('click',event=>{event.stopImmediatePropagation();
  const count=state.mappings.length;
  showModal('双人桌宠近期变化',count?`<p>当前关系组在${state.scene==='home'?'老屋':'花园'}有 ${count} 个已映射意象。${state.quiet?'桌宠已休眠，不会主动播放动效。':'桌宠在此安静陪伴。'}</p>`:'<p>当前场景暂无已映射记录。桌宠正在安静休息。</p>',`<button class="btn primary" data-quiet>${state.quiet?'唤醒桌宠':'一键休眠'}</button><button class="btn" data-modal-close>关闭</button>`);
 },{capture:true}));
 app.querySelector('[data-memorial]')?.addEventListener('click',event=>{event.stopImmediatePropagation();const monument=state.monument;if(!monument)return;const marks=monument.marks.map(mark=>`<li>${new Date(mark.confirmedAt).toLocaleDateString('zh-CN')} · ${mark.markType==='light'?'柔和光点':mark.markType==='ring'?'环形刻痕':'修复纹理'}</li>`).join('');showModal('对齐纪念',`<p><span class="tag">${monument.isDemo?'演示数据':''}</span></p><dl class="detail-facts"><div><dt>完成日期</dt><dd>${new Date(monument.confirmedAt).toLocaleDateString('zh-CN')}</dd></div><div><dt>确认次数</dt><dd>${monument.confirmedAlignmentCount}</dd></div><div><dt>中性摘要</dt><dd>${esc(monument.summary)}</dd></div></dl><ul>${marks}</ul>`,`<button class="btn primary" data-alignment-source="${esc(monument.latestAlignmentId)}">查看对齐记录</button><button class="btn" data-modal-close>关闭</button>`)},{capture:true});
 app.querySelector('[data-phantom]')?.addEventListener('click',event=>{event.stopImmediatePropagation();showModal('尚未完成的理解差异','<p>这里表示一处尚未完成的理解整理。它可以被忽略，也可以由你主动发起认知对齐；不会自动复制任何一方原文。</p>',`<button class="btn primary" data-start-related-alignment>发起认知对齐</button><button class="btn" data-modal-close>暂不处理</button>`)},{capture:true});
 app.querySelector('[data-start-related-alignment]')?.addEventListener('click',()=>go(`/r/${state.group}/workspace/alignment`));
 app.querySelector('[data-alignment-source]')?.addEventListener('click',e=>go(`/r/${state.group}/workspace/alignment/${encodeURIComponent(e.currentTarget.dataset.alignmentSource)}`));
}
