async function submitRecord(e){e.preventDefault();const form=e.currentTarget,fd=new FormData(form),text=String(fd.get('content')||''),vis=fd.get('visibility')||'self',kind=state.kind==='image'?'image':state.kind==='audio'?'audio':'text';let analysis;try{analysis=await agent.preprocess({relationId:state.group,purpose:state.purpose,content:text})}catch(error){const message=error instanceof AgentApiError?error.message:'Agent 后端请求失败';showModal('Agent 处理失败',esc(message));return}if(analysis.safetyStatus==='paused'){showModal('安全边界提示',`${WORKSPACE_COPY.safetyBoundary}<p>${esc(analysis.message||'普通流程已暂停。')}</p>`);return}if((kind==='image'||kind==='audio')&&!fd.get('file')?.name){announce('请先选择本地文件');return}if(state.purpose==='emotion'&&text){const candidate=analysis.candidateText||text;app.querySelector('#candidate-area').innerHTML=`<div class="compare"><article><h3>你的原话</h3><p>${esc(text)}</p></article><article><h3>AI 润色候选（${analysis.provider==='mock'?'Mock Provider':'Agent Provider'}）</h3><p>${esc(candidate)}</p></article><article><h3>沟通建议与改动说明</h3><p>保留表达重点，降低指责性；选择由你决定，系统不会自动发送或覆盖原话。</p></article></div><div class="form-actions" role="group" aria-label="选择最终版本"><button type="button" class="btn primary" data-choice="candidate">使用润色版本</button><button type="button" class="btn" data-choice="original">保留原始版本</button><button type="button" class="btn danger" data-choice="abandon">放弃本次发送</button></div>`;app.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>chooseEmotion(b.dataset.choice,text,candidate,vis));return}const structured=state.purpose==='plan'?{date:fd.get('planDate'),time:fd.get('planTime'),timezone:fd.get('timezone'),place:fd.get('planPlace'),participants:fd.get('participants'),action:fd.get('action'),timeMeaning:fd.get('timeMeaning'),reminder:fd.get('reminder')}:null;if(state.purpose==='plan'&&/六点半|6点半/.test(text)&&!structured.timeMeaning){app.querySelector('#candidate-area').innerHTML=`<fieldset class="ambiguity"><legend>“六点半”是出发时间还是到达时间？</legend><p>一次只确认一个关键歧义。</p><label><input type="radio" name="timeMeaningChoice" value="出发时间">出发时间</label><label><input type="radio" name="timeMeaningChoice" value="到达时间">到达时间</label><button type="button" class="btn small" data-confirm-time>确认这个字段</button></fieldset>`;app.querySelector('[data-confirm-time]').onclick=()=>{const chosen=app.querySelector('[name=timeMeaningChoice]:checked')?.value;if(!chosen){announce('请选择时间含义');return}form.querySelector('[name=timeMeaning]').value=chosen;submitRecord(e)};return}if(state.purpose==='plan'&&planMissingFields(structured).length){announce('请先确认日期、时间、地点、动作及出发/到达语义。');return}const file=fd.get('file');const mediaUrl=file?.name?URL.createObjectURL(file):null;const title=fd.get('title')||`${state.purpose==='plan'?'计划':state.purpose==='emotion'?'情绪记录':'普通记忆'}（演示）`;const r=await repo.create({groupId:state.group,authorId:state.member,kind,purpose:state.purpose,title,summary:'用户确认的本地演示记录',visibility:vis,privateText:text,note:fd.get('note')||text,date:fd.get('date')||structured?.date,place:fd.get('place')||structured?.place,scene:state.scene,source:'user-demo',safe:true,mediaUrl,audioType:fd.get('audioType')||null,creator:fd.get('creator')||null,imageryType:fd.get('imageryType')||null,structured});if(vis==='self'){await repo.changeStatus(r.id,'pending-ai');await repo.changeStatus(r.id,'pending-user');await repo.changeStatus(r.id,'private');await refresh();showModal('已保存为仅自己可见','该记录进入私人档案，不会生成共享意象。');return}await repo.changeStatus(r.id,'pending-ai');await repo.changeStatus(r.id,'pending-user');if(state.purpose==='emotion'){const cool=await repo.changeStatus(r.id,'cooling');state.coolingId=r.id;state.tab='new';startCooling(cool.coolingEndsAt);return}await repo.changeStatus(r.id,'archived');if(kind==='image'||state.purpose==='plan'||kind==='audio'||state.purpose==='memory'){const mappingType=kind==='image'?(fd.get('imageryType')||'flower'):state.purpose==='plan'?'branch':kind==='audio'?'record':'plant';await repo.changeStatus(r.id,'mapped');await repo.update(r.id,x=>({...x,mappingId:`map-${r.id}`,mappingType,scene:state.scene,summary:title,updatedAt:Date.now()}))}await refresh();showModal('记录已确认并归档','演示记录已同步到档案与对应场景。')}
function startCooling(end){state.coolingEnd=end;state.modal={title:'情绪表达冷静期',body:`<p>演示冷静期：<b id="cool-clock">60</b> 秒。</p><p>倒计时结束前可取消；期间不会生成共享意象。</p><div class="form-actions"><button class="btn danger" data-cancel-cooling>取消发送</button></div>`,actions:''};render();const complete=async()=>{clearInterval(state.timer);const id=state.coolingId;await repo.changeStatus(id,'archived');const r=await repo.getRecord(state.group,id,state.member);if(r?.visibility==='group'){await repo.changeStatus(id,'mapped');await repo.update(id,x=>({...x,mappingId:`map-${id}`,mappingType:'plant',summary:'由已确认情绪表达转译的中性场景变化',scene:state.scene,updatedAt:Date.now()}))}await refresh();state.modal={title:'冷静期结束',body:'记录已归档；如允许关系组查看，将以中性环境变化呈现，不显示原话。'};render()};const tick=()=>{const left=Math.max(0,Math.ceil((state.coolingEnd-Date.now())/1000));const el=document.querySelector('#cool-clock');if(el)el.textContent=String(left);if(left===0)complete()};state.timer=setInterval(tick,250);tick();app.querySelector('[data-cancel-cooling]')?.addEventListener('click',async()=>{clearInterval(state.timer);await repo.changeStatus(state.coolingId,'abandoned');await refresh();state.modal=null;render();announce('已取消发送，未生成共享意象')})}
async function chooseEmotion(choice,text,candidate,vis){if(choice==='abandon'){state.kind=null;render();announce('已放弃本次发送，未保存记录且未生成意象');return}const r=await repo.create({groupId:state.group,authorId:state.member,kind:'text',purpose:'emotion',title:'情绪表达（演示）',summary:'用户确认版本，冷静期后处理',visibility:vis,privateText:text,candidate,finalChoice:choice,scene:state.scene,source:'user-demo'});await repo.changeStatus(r.id,'pending-ai');await repo.changeStatus(r.id,'pending-user');const c=await repo.changeStatus(r.id,'cooling');state.coolingId=r.id;startCooling(c.coolingEndsAt)}
function reviewAlignment(yes){repo.updateAlignment(a=>{const p=a.participants.find(x=>x.id===state.member);p.reviewed=true;if(!yes)p.reviewNote='用户标记不是我的意思';}).then(()=>refresh()).then(()=>{render();announce(yes?'已确认本人解析':'已标记需要修订')})}
function confirmDelete(id){showModal('确认删除记录？','删除后该演示记录将从档案与场景中移除。',`<button class="btn danger" data-confirm-delete="${esc(id)}">确认删除</button><button class="btn" data-modal-close>取消</button>`);app.querySelector('[data-confirm-delete]')?.addEventListener('click',async()=>{await repo.delete(id);state.modal=null;state.detail=null;await refresh();render();announce('记录已删除并同步场景')})}
async function animateDiscToGramophone(discId){
 const source=app.querySelector(`[data-object="${CSS.escape(discId)}"] .disc-art`),target=app.querySelector('[data-gramophone]');
 if(state.reduceMotion||!source||!target)return;
 const from=source.getBoundingClientRect(),to=target.getBoundingClientRect();
 const clone=source.cloneNode(true);clone.className='disc-flight';clone.setAttribute('aria-hidden','true');
 Object.assign(clone.style,{position:'fixed',left:`${from.left}px`,top:`${from.top}px`,width:`${from.width}px`,height:`${from.height}px`,zIndex:'88',pointerEvents:'none'});document.body.append(clone);
 await clone.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${to.left+to.width*.56-from.left-from.width/2}px,${to.top+to.height*.52-from.top-from.height/2}px) scale(.72)`,opacity:.92}],{duration:520,easing:'cubic-bezier(.16,1,.3,1)',fill:'forwards'}).finished.catch(()=>{});clone.remove();
}
function playAudio(){
 if(!state.currentDiscId){showModal('记忆留声机','请先从唱片收藏中选择一张唱片。');return}
 if(!state.audioFile){state.playing=false;announce('当前演示唱片未提供音频文件。请先在页面 B 上传音频。');showModal('音频文件尚未提供','预置唱片只用于展示映射。上传本地音频后可在本次会话中播放；不会自动播放。');return}
 if(!state.audioElement){
  state.audioObjectUrl=URL.createObjectURL(state.audioFile);state.audioElement=new Audio(state.audioObjectUrl);state.audioElement.preload='metadata';state.audioElement.volume=(state.audioVolume??50)/100;
  state.audioElement.addEventListener('timeupdate',()=>{state.audioProgress=state.audioElement.duration?state.audioElement.currentTime/state.audioElement.duration:0;const progress=app.querySelector('[data-progress]');if(progress)progress.value=String(Math.round(state.audioProgress*100))});
  state.audioElement.addEventListener('ended',()=>{state.playing=false;state.audioProgress=0;render()});
  state.audioElement.addEventListener('error',()=>{state.playing=false;announce('音频加载失败；请重新选择本地文件。');showModal('音频加载失败','无法读取这段本地音频。请返回页面 B 重新选择文件。')});
 }
 if(state.playing){state.audioElement.pause();state.playing=false;announce('已暂停播放');render();return}
 state.audioElement.play().then(()=>{state.playing=true;render();announce('记忆唱片开始播放')}).catch(()=>{state.playing=false;showModal('需要再次确认播放','浏览器阻止了本次播放。请关闭提示后，再点击留声机开始播放。')});
}
function focusSelector(element){
  if(!element)return null;
  if(element.id)return `#${CSS.escape(element.id)}`;
  const entry=Object.entries(element.dataset||{})[0];
  if(!entry)return null;
  const [key,value]=entry;
  const attribute=key.replace(/[A-Z]/g,letter=>`-${letter.toLowerCase()}`);
  return value?`[data-${attribute}="${CSS.escape(value)}"]`:`[data-${attribute}]`;
}
function showModal(title,body,actions){state.returnFocus=focusSelector(document.activeElement);state.modal={title,body,actions};render();app.querySelector('[data-modal-close]')?.focus()}
function closeModal(){const selector=state.returnFocus;state.modal=null;render();if(selector)app.querySelector(selector)?.focus();state.returnFocus=null}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){e.preventDefault();closeModal();return}if(e.key==='Tab'&&state.modal){const modal=app.querySelector('.modal');const focusable=[...modal?.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')||[]];if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('click',event=>{if(event.target.closest?.('[data-quiet]'))queueMicrotask(()=>saveUiPreference('mg-pets-quiet',state.quiet));if(event.target.closest?.('[data-veil]'))queueMicrotask(()=>saveUiPreference('mg-memory-veil',state.veil));if(event.target.closest?.('[data-caption]'))queueMicrotask(()=>saveUiPreference('mg-captions',state.captions!==false))},{capture:true});
document.addEventListener('input',event=>{if(!event.target.matches?.('[data-volume]'))return;queueMicrotask(()=>{state.audioVolume=Number(event.target.value);saveUiPreference('mg-record-volume',state.audioVolume);if(state.audioElement)state.audioElement.volume=state.audioVolume/100})},{capture:true});
document.addEventListener('visibilitychange',()=>document.documentElement.classList.toggle('page-hidden',document.hidden));
window.addEventListener('pagehide',()=>{clearTimeout(state.motionTimer);clearInterval(state.timer);state.motionCleanup?.();if(state.audioElement){state.audioElement.pause();state.audioElement.src=''}if(state.audioObjectUrl)URL.revokeObjectURL(state.audioObjectUrl)});
async function init(){state.render=render;route();await refresh();if(state.detail){state.tab='archive'}if(location.pathname==='/')history.replaceState({},'',`/r/${state.group}/space/${state.scene}`);const expired=state.records.filter(r=>r.status==='cooling'&&r.coolingEndsAt<=Date.now());for(const record of expired)await repo.changeStatus(record.id,'archived');if(expired.length)await refresh();const cooling=state.records.find(r=>r.status==='cooling'&&r.coolingEndsAt>Date.now());if(cooling){state.coolingId=cooling.id;startCooling(cooling.coolingEndsAt)}else render()}
